import{_ as s,o as e,c as n,a6 as r}from"./chunks/framework.QBF2cGGQ.js";const u=JSON.parse('{"title":"17 · TypeScript 深入","description":"","frontmatter":{},"headers":[],"relativePath":"guide/17-typescript.md","filePath":"guide/17-typescript.md","lastUpdated":1793328769000}'),a={name:"guide/17-typescript.md"};function i(t,o,c,p,l,d){return e(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="_17-·-typescript-深入" tabindex="-1">17 · TypeScript 深入 <a class="header-anchor" href="#_17-·-typescript-深入" aria-label="Permalink to &quot;17 · TypeScript 深入&quot;">​</a></h1><blockquote><p><strong>投入权重：8%</strong> · 这一章不在原来的 14 个模块里，是补的。</p><p>原因很直接：AI 应用里 TS 不只是写组件，它要承担<strong>工具 schema、流式事件、Agent 状态机、API 契约</strong>。这些地方类型错了，运行时才炸，而且炸得很难查。</p></blockquote><h2 id="为什么-ai-应用特别需要-ts" tabindex="-1">为什么 AI 应用特别需要 TS <a class="header-anchor" href="#为什么-ai-应用特别需要-ts" aria-label="Permalink to &quot;为什么 AI 应用特别需要 TS&quot;">​</a></h2><p>三个具体场景，都是类型系统直接救命的地方：</p><p><strong>一、工具定义。</strong> 你给模型的 tool schema 和你在代码里执行的函数，必须是同一份定义。手写两份必然漂移——模型按 A 填参数，你按 B 解析，出错时你甚至不知道是谁的错。用 TS 从类型推导 schema，或者用 zod 定义后反推类型，才能保证一致。</p><p><strong>二、流式事件。</strong> SSE 推过来的事件有六七种（text-delta / tool-call / tool-result / reasoning / done / error），每种字段不同。没有 discriminated union，你的 switch 里全是 <code>as any</code>，加一种事件就漏一处。</p><p><strong>三、Agent 状态机。</strong> 一个 Agent 运行有十几个状态，每个状态允许的动作不同。用联合类型表达，编译器能帮你拦住&quot;在等待审批时调用了执行工具&quot;这类错误。</p><h2 id="类型系统核心" tabindex="-1">类型系统核心 <a class="header-anchor" href="#类型系统核心" aria-label="Permalink to &quot;类型系统核心&quot;">​</a></h2><ul><li><strong>类型标注与推断</strong> <span class="prio prio-must">必须</span> — 标注是约束，推断是省事。函数返回值建议显式标注（防止实现变化导致调用方静默出错）。</li><li><strong><code>interface</code> 与 <code>type</code> 的区别</strong> <span class="prio prio-must">必须</span> — interface 可声明合并、适合对象契约；type 能表达联合、交叉、条件类型。<strong>团队约定一个默认，别混着用。</strong></li><li><strong>可选属性与 <code>exactOptionalPropertyTypes</code></strong> <span class="prio prio-imp">重要</span> — <code>a?: string</code> 和 <code>a: string | undefined</code> 在严格模式下不等价。开这个选项能抓到一批&quot;传了 undefined 覆盖了默认值&quot;的 bug。</li><li><strong>联合类型</strong> <span class="prio prio-must">必须</span> — AI 场景到处都是联合：<code>Content = TextPart | ImagePart | ToolCallPart</code>。</li><li><strong>字面量类型与 <code>as const</code></strong> <span class="prio prio-must">必须</span> — 工具名、事件类型、模型 ID 都应该是字面量联合，而不是 string。写错一个字母编译期就报。</li><li><strong>类型收窄（narrowing）</strong> <span class="prio prio-must">必须</span> — <code>typeof</code> / <code>in</code> / <code>instanceof</code> / 判别属性。<strong>判别联合（discriminated union）是处理流式事件的标准姿势</strong>。</li><li><strong><code>unknown</code> 与 <code>any</code></strong> <span class="prio prio-must">必须</span> — 外部输入（API 响应、JSON.parse、工具返回值）一律 <code>unknown</code>，校验后再用。<code>any</code> 会让整条链路失去保护。</li><li><strong><code>never</code> 与穷尽检查</strong> <span class="prio prio-imp">重要</span> — switch 处理事件类型时，default 分支写 <code>const _: never = evt</code>，新增事件类型时编译器会提醒你。</li><li><strong>类型断言的风险</strong> <span class="prio prio-imp">重要</span> — <code>as</code> 是&quot;我保证&quot;，不是&quot;我检查&quot;。用在校验之后，不要用在校验之前。</li></ul><h2 id="泛型" tabindex="-1">泛型 <a class="header-anchor" href="#泛型" aria-label="Permalink to &quot;泛型&quot;">​</a></h2><ul><li><strong>函数泛型</strong> <span class="prio prio-must">必须</span> — 工具执行器、结果包装器这类通用逻辑必须泛型化。</li><li><strong>泛型约束 <code>extends</code></strong> <span class="prio prio-must">必须</span> — 约束到&quot;有 id 字段&quot;这类最小契约，而不是约束到具体类型。</li><li><strong>泛型默认值</strong> <span class="prio prio-imp">重要</span> — 让常见用法不用显式传参。</li><li><strong><code>keyof</code> 与索引访问类型</strong> <span class="prio prio-imp">重要</span> — 从对象类型取键，做类型安全的字段访问。</li><li><strong><code>infer</code></strong> <span class="prio prio-imp">重要</span> — 从函数返回值、数组元素、Promise 内部提取类型。写通用工具时用。</li><li><strong>条件类型</strong> <span class="prio prio-imp">重要</span> — <code>T extends X ? A : B</code>，配 <code>infer</code> 能做类型转换。</li><li><strong>映射类型</strong> <span class="prio prio-imp">重要</span> — 把一组字段批量变成可选/只读/可空。</li><li><strong>模板字面量类型</strong> <span class="prio prio-opt">选学</span> — 拼字符串类型，做事件名、路由名的约束。</li></ul><p><strong>别陷进类型体操。</strong> <code>type-challenges</code> 做前 20 题足够。工程里的类型是为了防错，不是为了炫技。写出三层嵌套的条件类型，三个月后你自己也看不懂。</p><h2 id="工具类型-实际会用到的那几个" tabindex="-1">工具类型（实际会用到的那几个） <a class="header-anchor" href="#工具类型-实际会用到的那几个" aria-label="Permalink to &quot;工具类型（实际会用到的那几个）&quot;">​</a></h2><ul><li><strong><code>Partial</code> / <code>Required</code></strong> <span class="prio prio-must">必须</span> — 更新接口的参数、配置的默认值合并。</li><li><strong><code>Pick</code> / <code>Omit</code></strong> <span class="prio prio-must">必须</span> — 从数据库模型派生 API 响应类型（去掉 password、internal 字段），这是最常用的模式。</li><li><strong><code>Record</code></strong> <span class="prio prio-must">必须</span> — 模型注册表、工具注册表。</li><li><strong><code>ReturnType</code> / <code>Parameters</code></strong> <span class="prio prio-imp">重要</span> — 从函数反推类型，避免重复定义。</li><li><strong><code>Awaited</code></strong> <span class="prio prio-imp">重要</span> — 取 Promise 内部类型。</li><li><strong><code>NonNullable</code> / <code>Exclude</code></strong> <span class="prio prio-opt">选学</span> — 从联合里排除。</li></ul><h2 id="运行时校验-zod" tabindex="-1">运行时校验：zod <a class="header-anchor" href="#运行时校验-zod" aria-label="Permalink to &quot;运行时校验：zod&quot;">​</a></h2><p>类型在编译后消失，但 AI 应用面对的全是不可信输入——模型输出的 JSON、第三方 API、工具返回值。<strong>必须有运行时校验。</strong></p><ul><li><strong>Schema 定义</strong> <span class="prio prio-must">必须</span> — <code>z.object({...})</code>，字段级约束（长度、范围、枚举）。</li><li><strong><code>z.infer</code> 反推类型</strong> <span class="prio prio-must">必须</span> — 一份定义同时得到运行时校验和编译期类型，<strong>这是消除重复的唯一正确做法</strong>。</li><li><strong><code>safeParse</code> 与错误处理</strong> <span class="prio prio-must">必须</span> — 不要用 <code>parse</code> 抛异常，用 <code>safeParse</code> 拿结构化错误，把错误信息回喂给模型让它修正。</li><li><strong><code>z.discriminatedUnion</code></strong> <span class="prio prio-must">必须</span> — 流式事件、工具调用的标准写法。</li><li><strong><code>z.coerce</code></strong> <span class="prio prio-imp">重要</span> — 模型经常把数字写成字符串，<code>z.coerce.number()</code> 能救一批。</li><li><strong>Schema 转 JSON Schema</strong> <span class="prio prio-must">必须</span> — 用 <code>zod-to-json-schema</code> 直接把 zod 定义喂给模型的 tool schema，保证两边一致。</li><li><strong>默认值与可选</strong> <span class="prio prio-imp">重要</span> — <code>.default()</code> 在 AI 场景很关键，模型经常漏字段。</li><li><strong>错误信息要能指导模型</strong> <span class="prio prio-must">必须</span> — 校验失败时返回&quot;字段 X 应为枚举值 [a,b,c]，你传的是 d&quot;，而不是&quot;validation failed&quot;。</li></ul><h2 id="类型安全的-api-契约" tabindex="-1">类型安全的 API 契约 <a class="header-anchor" href="#类型安全的-api-契约" aria-label="Permalink to &quot;类型安全的 API 契约&quot;">​</a></h2><ul><li><strong>前后端共享类型</strong> <span class="prio prio-must">必须</span> — monorepo 里放一个 <code>packages/shared</code>，或者用 OpenAPI 生成。手写两份必然漂移。</li><li><strong>响应类型与数据库模型分离</strong> <span class="prio prio-must">必须</span> — 数据库模型不能直接当 API 响应，会泄露内部字段。</li><li><strong>错误类型也建模</strong> <span class="prio prio-must">必须</span> — 统一错误结构 <code>{ code, message, detail }</code>，用联合类型枚举 code。</li><li><strong><code>satisfies</code> 运算符</strong> <span class="prio prio-imp">重要</span> — 既校验类型又保留字面量推断，写配置对象时特别有用。</li><li><strong>品牌类型（branded type）</strong> <span class="prio prio-opt">选学</span> — 区分 <code>UserId</code> 和 <code>TenantId</code>，防止传错参数。AI 场景里权限参数传错是安全事故。</li></ul><h2 id="tsconfig-关键项" tabindex="-1">tsconfig 关键项 <a class="header-anchor" href="#tsconfig-关键项" aria-label="Permalink to &quot;tsconfig 关键项&quot;">​</a></h2><ul><li><strong><code>strict: true</code></strong> <span class="prio prio-must">必须</span> — 这是底线。不开 strict 的 TS 约等于加了注释的 JS。</li><li><strong><code>noUncheckedIndexedAccess</code></strong> <span class="prio prio-must">必须</span> — 数组下标访问返回 <code>T | undefined</code>。能抓到一批&quot;数组为空时崩了&quot;的 bug。</li><li><strong><code>exactOptionalPropertyTypes</code></strong> <span class="prio prio-imp">重要</span> — 区分&quot;没有这个字段&quot;和&quot;字段是 undefined&quot;。</li><li><strong><code>noImplicitOverride</code></strong> <span class="prio prio-opt">选学</span> — 类继承时强制写 override。</li><li><strong><code>verbatimModuleSyntax</code></strong> <span class="prio prio-opt">选学</span> — 明确区分类型导入和值导入，打包体积更可控。</li><li><strong><code>moduleResolution: bundler</code></strong> <span class="prio prio-imp">重要</span> — 现代项目的默认，别再用手写的 paths 别名硬凑。</li></ul><h2 id="在-ai-场景的具体用法" tabindex="-1">在 AI 场景的具体用法 <a class="header-anchor" href="#在-ai-场景的具体用法" aria-label="Permalink to &quot;在 AI 场景的具体用法&quot;">​</a></h2><ul><li><strong>工具定义只写一次</strong> <span class="prio prio-must">必须</span> — 用 zod 定义参数，<code>z.infer</code> 得类型，<code>zodToJsonSchema</code> 得 schema。三处一致，不会漂移。</li><li><strong>流式事件用判别联合</strong> <span class="prio prio-must">必须</span> — <code>type StreamEvent = { type:&#39;text&#39;, delta:string } | { type:&#39;tool_call&#39;, id:string, name:string, args:unknown } | ...</code>。</li><li><strong>Agent 状态机用联合类型</strong> <span class="prio prio-must">必须</span> — 每个状态带自己的数据，<code>switch</code> 时编译器强制你处理所有分支。</li><li><strong>模型输出先 <code>unknown</code> 再校验</strong> <span class="prio prio-must">必须</span> — <code>JSON.parse</code> 的结果就是 <code>unknown</code>，别直接 <code>as</code>。</li><li><strong>权限参数用品牌类型</strong> <span class="prio prio-imp">重要</span> — 防止把 <code>userId</code> 传到 <code>tenantId</code> 的位置。</li></ul><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><p>把现有项目开到 <code>strict</code> + <code>noUncheckedIndexedAccess</code> 全绿，并且：</p><ul><li>工具定义没有一处手写 JSON Schema</li><li>流式事件的 switch 有穷尽检查</li><li>所有外部输入都经过 zod 校验</li><li>没有 <code>as any</code>（除了极少数标注了原因的）</li></ul><p><strong>这是能写进简历的一句话</strong>：「将项目迁移到 strict 模式并引入 zod 做运行时校验，消除 30+ 处类型逃逸，工具定义与 schema 由单一来源生成。」</p>',27)])])}const m=s(a,[["render",i]]);export{u as __pageData,m as default};
